/**
 * The chat kit's transport layer (SPEC 13 §8 "Clients"): one RealtimeClient for the four member apps, over Ably in
 * production and over the local SSE hub in development. Which one is decided by api2's token answer
 * (`POST /v1/realtime/token` → `driver`). No React here: the hooks (`useConversationChannel`, `useAccountChannel`)
 * come with chat in W3 and sit on top of this.
 *
 * The apps install the transport's runtime themselves and hand it in, so contracts keeps importing only zod:
 * - Ably: `npm install ably` (web and Expo), then `createRealtimeClient({ api, Ably: { Realtime } })` with
 *   the `Realtime` class of the ably package.
 * - Local SSE: browsers have `EventSource`; Expo passes one (`react-native-sse`) as `EventSource`.
 *
 *   const rt = createRealtimeClient({ api, baseUrl, Ably: { Realtime }, EventSource });
 *   const off = rt.subscribe(accountChannel(me.id), (m) => { if (m.name === "notification.new") ... });
 *   rt.onState((s) => ...);          // connecting | connected | reconnecting | offline | closed
 *   rt.onResume(() => refetchHistory());   // after any reconnect: refetch since the last message id
 *   rt.setOnline(navigator.onLine);  // NetInfo / online-offline events; app foreground → rt.reconnect()
 *
 * Typing channels are peer to peer (each member publishes on their own): the kit delivers only a well-formed
 * `typing { on }` event from them and drops anything else, so nothing unmoderated reaches the app.
 * A token answer of 401 (signed out) stops the retries and calls `onUnauthorized` (the app signs out at once);
 * `reconnect()` after signing in starts again.
 */
import type { Client } from "./client";
import { parseChannel, type RealtimeMessage, type RealtimeToken, realtimeTokenSchema, typingChannel, typingEventSchema } from "./realtime";

export type ConnectionState = "idle" | "connecting" | "connected" | "reconnecting" | "offline" | "closed";

export interface RealtimeClient {
  readonly state: ConnectionState;
  /** which driver api2 chose (null until the first token) */
  readonly driver: RealtimeToken["driver"] | null;
  /** starts connecting (subscribe also starts it) */
  connect(): void;
  subscribe(channel: string, fn: (msg: RealtimeMessage) => void): () => void;
  /** typing on / off on the caller's own typing channel of this conversation */
  publishTyping(conversationId: string, accountId: string, on: boolean): Promise<void>;
  onState(fn: (state: ConnectionState) => void): () => void;
  /** called after every reconnect (not the first connect): refetch what may have been missed */
  onResume(fn: () => void): () => void;
  /** the device's network state: offline closes the connection, online reconnects */
  setOnline(online: boolean): void;
  /** reconnect now (the app came back to the foreground) */
  reconnect(): void;
  /**
   * True when the current token covers `channel` (null before the first token). A conversation created or joined after
   * the token was issued is not in it: call `reauthorize()` (the chat kit does it when it subscribes).
   */
  covers(channel: string): boolean | null;
  /** fetches a fresh token now and moves the connection onto it (new conversations join the capability) */
  reauthorize(): Promise<void>;
  close(): void;
}

