const BACKOFF = [1000, 2000, 5000, 10_000, 30_000];

interface Transport {
  open(): void;
  close(): void;
  watch(channel: string): void;
  unwatch(channel: string): void;
  publishTyping(channel: string, on: boolean): Promise<void>;
  reauthorize(): Promise<void>;
}

interface TransportEvents {
  state(s: ConnectionState): void;
  message(m: RealtimeMessage): void;
  /** the token route answered 401 */
  unauthorized(): void;
  /** a token was fetched (its capability is what `covers` checks) */
  token(t: RealtimeToken): void;
  /** the token source (the app's, or the default route) */
  getToken?: () => Promise<RealtimeToken>;
}

/** `POST /v1/realtime/token`; a failure carries the api error (`signedOut` reads it). */
export async function requestRealtimeToken(api: Client): Promise<RealtimeToken> {
  const r = await api.post("/v1/realtime/token", undefined, { schema: realtimeTokenSchema });
  if (!r.ok) throw Object.assign(new Error(r.error.message), { error: r.error });
  return r.data;
}

async function fetchToken(api: Client, ev: Pick<TransportEvents, "unauthorized" | "token" | "getToken">): Promise<RealtimeToken> {
  try {
    const t = await (ev.getToken ? ev.getToken() : requestRealtimeToken(api));
    ev.token(t);
    return t;
  } catch (e) {
    if (signedOut(e)) ev.unauthorized();
    throw e;
  }
}

/** The channels a token lets its holder subscribe to. */
export function tokenChannels(t: RealtimeToken): Set<string> {
  let cap: Record<string, string[]> = {};
  if (t.driver === "local") cap = t.capability;
  else {
    try {
      cap = JSON.parse(t.tokenRequest.capability) as Record<string, string[]>;
    } catch {
      cap = {};
    }
  }
  return new Set(Object.keys(cap).filter((c) => (cap[c] ?? []).includes("subscribe")));
}

/** The token route answered 401: the member is signed out, and retrying cannot help. */
function signedOut(e: unknown): boolean {
  const err = (e as { error?: { kind?: string; status?: number } } | null)?.error;
  return err?.kind === "api" && err.status === 401;
}

const wait = (ms: number) => new Promise<void>((r) => setTimeout(r, ms));

function ablyTransport(Realtime: AblyRealtimeCtor, api: Client, ev: TransportEvents): Transport {
  let client: AblyRealtimeLike | null = null;
  const watched = new Set<string>();
  const attach = (name: string) => {
    client?.channels.get(name).subscribe((m) => ev.message({ id: m.id ?? "", channel: name, name: m.name ?? "", data: m.data }));
  };
  return {
    open() {
      if (client) return client.connection.connect();
      client = new Realtime({
        autoConnect: true,
        echoMessages: false,
        closeOnUnload: true,
        authCallback: (_params, cb) => {
          fetchToken(api, ev).then(
            (t) => (t.driver === "ably" ? cb(null, t.tokenRequest) : cb(new Error("api2 is not on the Ably driver"), null)),
            // a 403 from authCallback is fatal to Ably (RSA4d): signed out, it stops retrying
            (e: unknown) => cb(signedOut(e) ? Object.assign(new Error("signed out"), { statusCode: 403, code: 40300 }) : e, null),
          );
        },
      });
      client.connection.on((c) => {
        const map: Record<string, ConnectionState> = { initialized: "connecting", connecting: "connecting", connected: "connected", disconnected: "reconnecting", suspended: "offline", closing: "closed", closed: "closed", failed: "closed" };
        ev.state(map[c.current] ?? "reconnecting");
      });
      for (const name of watched) attach(name);
    },
    close() {
      client?.connection.close();
    },
    watch(name) {
      if (watched.has(name)) return;
      watched.add(name);
      attach(name);
    },
    unwatch(name) {
      watched.delete(name);
      const ch = client?.channels.get(name);
      ch?.unsubscribe();
      void ch?.detach?.();
    },
    async publishTyping(channel, on) {
      if (!client) throw new Error("not connected");
      await client.channels.get(channel).publish("typing", { on });
    },
    async reauthorize() {
      if (!client?.auth) return;
      await client.auth.authorize();
      // channels refused under the old token attach again with the new capability
      for (const name of watched) {
        client.channels.get(name).unsubscribe();
        attach(name);
      }
    },
  };
}

/** The local SSE hub: one stream with every channel the token allows; the kit filters per subscription. */
function localTransport(ES: EventSourceCtor, api: Client, baseUrl: string, ev: TransportEvents, backoff: number[], first: RealtimeToken | null): Transport {
  let es: EventSourceLike | null = null;
  let token: Extract<RealtimeToken, { driver: "local" }> | null = first && first.driver === "local" ? first : null;
  let failures = 0;
  let timer: ReturnType<typeof setTimeout> | null = null;
  let closed = false;
  /** bumped by every open / close: a connect or a handler of an older generation does nothing */
  let gen = 0;
  const base = baseUrl.replace(/\/+$/, "");

  const fresh = (t: RealtimeToken | null) => !!t && t.driver === "local" && Date.parse(t.expiresAt) - Date.now() > 30_000;

  const stopStream = () => {
    es?.close();
    es = null;
  };

  const retry = (g: number) => {
    if (closed || g !== gen) return;
    ev.state("reconnecting");
    const delay = backoff[Math.min(failures, backoff.length - 1)] ?? 5000;
    failures++;
    if (timer) clearTimeout(timer);
    timer = setTimeout(() => void connect(g), delay);
  };

  const connect = async (g: number) => {
    timer = null;
    if (closed || g !== gen) return;
    try {
      if (!fresh(token)) {
        const t = await fetchToken(api, ev);
        if (t.driver !== "local") throw new Error("api2 is not on the local driver");
        token = t;
      }
    } catch (e) {
      if (closed || g !== gen) return;
      if (signedOut(e)) {
        closed = true;
        return ev.state("closed");
      }
      return retry(g);
    }
    if (closed || g !== gen) return; // closed or reopened while the token was on its way
    const t = token!;
    stopStream();
    const mine = new ES(`${base}${t.streamPath}?token=${encodeURIComponent(t.token)}`, { pollingInterval: 0 });
    es = mine;
    const current = () => es === mine && g === gen && !closed;
    mine.addEventListener("ready", () => {
      if (!current()) return;
      failures = 0;
      ev.state("connected");
    });
    mine.addEventListener("message", (e) => {
      if (!current()) return;
      try {
        const m = JSON.parse(String(e.data)) as RealtimeMessage;
        if (m && typeof m.channel === "string" && typeof m.name === "string") ev.message(m);
      } catch {
        /* not ours */
      }
    });
    mine.addEventListener("expired", () => {
      if (!current()) return;
      token = null;
      stopStream();
      void connect(g);
    });
    const onError = () => {
      // never let the EventSource retry with the same (maybe expired) token: a fresh one, with a backoff
      if (!current()) return;
      stopStream();
      token = null;
      retry(g);
    };
    mine.addEventListener("error", onError); // react-native-sse only calls listeners
    mine.onerror = onError; // browsers call both: the second finds the stream already replaced
  };

  return {
    open() {
      closed = false;
      gen++;
      if (timer) clearTimeout(timer);
      timer = null;
      ev.state("connecting");
      void connect(gen);
    },
    close() {
      closed = true;
      gen++;
      if (timer) clearTimeout(timer);
      timer = null;
      stopStream();
    },
    watch() {},
    unwatch() {},
    async reauthorize() {
      token = null;
      if (closed) return;
      gen++;
      if (timer) clearTimeout(timer);
      timer = null;
      await connect(gen);
    },
    async publishTyping(channel, on) {
      if (!fresh(token)) token = (await fetchToken(api, ev)) as typeof token;
      if (!token || token.driver !== "local") throw new Error("api2 is not on the local driver");
      const r = await api.post(token.publishPath, { token: token.token, channel, name: "typing", data: { on } });
      if (!r.ok) throw Object.assign(new Error(r.error.message), { error: r.error });
    },
  };
}

/** Only `typing { on }` passes on a typing channel (peer to peer, never moderated); other channels pass as they are. */
function acceptable(m: RealtimeMessage): boolean {
  const ch = parseChannel(m.channel);
  if (ch?.kind !== "typing") return true;
  return m.name === "typing" && typingEventSchema.safeParse(m.data).success;
}

export function createRealtimeClient(opts: RealtimeClientOptions): RealtimeClient {
  let state: ConnectionState = "idle";
  let driver: RealtimeToken["driver"] | null = null;
  let transport: Transport | null = null;
  let starting: Promise<void> | null = null;
  let wasConnected = false;
  let online = true;
  let closed = false;
  const subs = new Map<string, Set<(m: RealtimeMessage) => void>>();
  const stateFns = new Set<(s: ConnectionState) => void>();
  const resumeFns = new Set<() => void>();
  /** ids seen recently per channel: a re-published event arrives once */
  const seen = new Map<string, string[]>();
  /** the subscribable channels of the newest token */
  let covered: Set<string> | null = null;
  /** the next token must be a new one (reauthorize), not a shared cached one */
  let forceFresh = false;
  const getToken = opts.getToken
    ? () => {
        const fresh = forceFresh;
        forceFresh = false;
        return opts.getToken!({ fresh });
      }
    : undefined;

  const setState = (s: ConnectionState) => {
    // while the device is offline every transport state reads as offline; only close() ends in closed
    if (!online && !closed) s = "offline";
    if (s === state) return;
    state = s;
    if (s === "connected") {
      if (wasConnected) for (const fn of resumeFns) fn();
      wasConnected = true;
    }
    for (const fn of stateFns) fn(s);
  };

  const deliver = (m: RealtimeMessage) => {
    const fns = subs.get(m.channel);
    if (!fns?.size || !acceptable(m)) return;
    if (m.id) {
      const ids = seen.get(m.channel) ?? [];
      if (ids.includes(m.id)) return;
      ids.push(m.id);
      if (ids.length > 200) ids.shift();
      seen.set(m.channel, ids);
    }
    for (const fn of fns) fn(m);
  };

  const events: TransportEvents = {
    state: setState,
    message: deliver,
    unauthorized: () => opts.onUnauthorized?.(),
    token: (t) => {
      covered = tokenChannels(t);
    },
    getToken,
  };

  const start = (): Promise<void> => {
    if (transport || starting || closed) return starting ?? Promise.resolve();
    setState("connecting");
    starting = (async () => {
      // the token answer picks the transport: retry it (with the backoff) rather than guess one
      const backoff = opts.backoffMs ?? BACKOFF;
      let first: RealtimeToken | null = null;
      for (let i = 0; !first; i++) {
        if (closed) return;
        try {
          first = await fetchToken(opts.api, events);
        } catch (e) {
          if (signedOut(e) || closed) throw e;
          setState("reconnecting");
          await wait(backoff[Math.min(i, backoff.length - 1)] ?? 5000);
        }
      }
      if (closed) return;
      if (first.driver === "ably") {
        if (!opts.Ably) throw new Error("api2 uses Ably: pass { Ably: { Realtime } } (npm install ably)");
        driver = "ably";
        transport = ablyTransport(opts.Ably.Realtime, opts.api, events);
      } else {
        const ES = opts.EventSource ?? (globalThis as { EventSource?: EventSourceCtor }).EventSource;
        if (!ES) throw new Error("the local realtime driver needs an EventSource");
        driver = "local";
        transport = localTransport(ES, opts.api, opts.baseUrl, events, backoff, first);
      }
      for (const ch of subs.keys()) transport.watch(ch);
      if (online) transport.open();
    })().finally(() => {
      starting = null;
    });
    return starting;
  };

  return {
    get state() {
      return state;
    },
    get driver() {
      return driver;
    },
    connect() {
      void start().catch(() => setState("closed"));
    },
    subscribe(channel, fn) {
      let set = subs.get(channel);
      if (!set) {
        set = new Set();
        subs.set(channel, set);
        transport?.watch(channel);
      }
      set.add(fn);
      void start().catch(() => setState("closed"));
      return () => {
        const s = subs.get(channel);
        s?.delete(fn);
        if (s && s.size === 0) {
          subs.delete(channel);
          seen.delete(channel);
          transport?.unwatch(channel);
        }
      };
    },
    async publishTyping(conversationId, accountId, on) {
      await start();
      if (!transport) throw new Error("realtime is not connected");
      await transport.publishTyping(typingChannel(conversationId, accountId), on);
    },
    onState(fn) {
      stateFns.add(fn);
      return () => stateFns.delete(fn);
    },
    onResume(fn) {
      resumeFns.add(fn);
      return () => resumeFns.delete(fn);
    },
    setOnline(next) {
      if (next === online) return;
      online = next;
      if (!next) {
        transport?.close();
        setState("offline");
      } else if (transport) {
        transport.open();
      } else void start().catch(() => setState("closed"));
    },
    covers(channel) {
      return covered ? covered.has(channel) : null;
    },
    async reauthorize() {
      if (closed) return;
      forceFresh = true;
      if (!transport) return start();
      await transport.reauthorize();
    },
    reconnect() {
      if (!online || closed) return;
      if (transport) {
        transport.close();
        transport.open();
      } else void start().catch(() => setState("closed"));
    },
    close() {
      closed = true;
      transport?.close();
      setState("closed");
    },
  };
}
